LECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t WHERE cafe_id NOT IN('948d09e1-93bd-4b23-be49-f1599603f4ba','f4c0146b-f2c3-4ced-a8dd-d505bb2e847d','80e930af-0795-4d79-aa5c-d9999bc46c1d','757079d2-1ada-4a1f-80e8-7abf5174d6a4','486af4c2-4a99-4dbd-881b-1f66f06dd247')),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t WHERE cafe_id NOT IN('948d09e1-93bd-4b23-be49-f1599603f4ba','f4c0146b-f2c3-4ced-a8dd-d505bb2e847d','80e930af-0795-4d79-aa5c-d9999bc46c1d','757079d2-1ada-4a1f-80e8-7abf5174d6a4','486af4c2-4a99-4dbd-881b-1f66f06dd247'))) snapshot;
